import{_ as a,o,c as t,a0 as r}from"./chunks/framework.BmDGRu32.js";const m=JSON.parse('{"title":"Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/concepts.md","filePath":"explanation/concepts.md"}'),c={name:"explanation/concepts.md"};function s(n,e,i,d,l,p){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to &quot;Concepts&quot;">​</a></h1><p>The domain vocabulary, each term defined once. The op-level contract lives in <a href="./../reference/ops.html">Reference: ops</a>.</p><h2 id="wal-write-ahead-log" tabindex="-1">WAL (write-ahead log) <a class="header-anchor" href="#wal-write-ahead-log" aria-label="Permalink to &quot;WAL (write-ahead log)&quot;">​</a></h2><p><code>refs/sturn/wal/&lt;ws&gt;</code> — the append-only op log per workspace, stored as ordinary git objects. <strong>The WAL is the state</strong>: anything derivable from it (bus cursors, materialized views, live claims) is a rebuildable cache.</p><h2 id="op" tabindex="-1">Op <a class="header-anchor" href="#op" aria-label="Permalink to &quot;Op&quot;">​</a></h2><p>The unit of coordination: <code>write</code>, <code>rename</code>, <code>delete</code>, <code>claim</code>, <code>release</code>, <code>intent</code>, <code>review</code>, <code>ask</code>/<code>answer</code>, <code>presence</code>. Ops are metadata about work — they never encode merge semantics. Content payloads become ODB blobs; ops reference them.</p><h2 id="workspace-ws" tabindex="-1">Workspace (<code>ws</code>) <a class="header-anchor" href="#workspace-ws" aria-label="Permalink to &quot;Workspace (`ws`)&quot;">​</a></h2><p>A named pointer — <code>refs/sturn/ws/&lt;name&gt;</code> → a commit — plus that workspace&#39;s WAL. Zero materialization: no clone, no worktree, no checkout. <code>sturn ws new</code> costs a ref.</p><h2 id="claim" tabindex="-1">Claim <a class="header-anchor" href="#claim" aria-label="Permalink to &quot;Claim&quot;">​</a></h2><p>An advisory lock on a resource URI (<code>fs:src/**</code>, <code>dev:display0</code>, <code>sess:T-012</code>) published <em>before</em> edits, with a TTL. Conflicts are learned in milliseconds on the claims topic — prevention, not merge-time discovery. <code>sturn check</code> probes the conflict set; <code>--fence</code> asks whether your claim was superseded.</p><h2 id="topic-bus" tabindex="-1">Topic / bus <a class="header-anchor" href="#topic-bus" aria-label="Permalink to &quot;Topic / bus&quot;">​</a></h2><p><code>repo.&lt;id&gt;.{ops,claims,review,presence,asks}</code> — the pub/sub cache the daemon fans WAL events onto. <strong>A cache, never authority</strong>: when the daemon is down, ops still sync through git push/fetch and subscribers replay the WAL.</p><h2 id="snap" tabindex="-1">Snap <a class="header-anchor" href="#snap" aria-label="Permalink to &quot;Snap&quot;">​</a></h2><p>The bridge back to ordinary git: folds a workspace&#39;s ops into a real commit on the branch. Multiple workspaces merge into ONE commit — rename-aware, semantic conflicts warn and later ops win.</p><h2 id="review-ask" tabindex="-1">Review / ask <a class="header-anchor" href="#review-ask" aria-label="Permalink to &quot;Review / ask&quot;">​</a></h2><p><code>review &lt;op-id&gt; approve|reject</code> is itself an attributed op — per-op approval that streams <em>before</em> commit time. <code>[review] require = true</code> makes <code>snap</code> refuse unreviewed ops. <code>ask</code> opens a pending-response question any actor may answer; <code>wait</code> blocks on the verdict.</p><h2 id="actor" tabindex="-1">Actor <a class="header-anchor" href="#actor" aria-label="Permalink to &quot;Actor&quot;">​</a></h2><p>Who you are on the ops you append — <code>STURN_ACTOR</code> env or config. Every op is attributed and (optionally) signed; <code>sturn verify</code> checks signatures against <code>allowed_signers</code>.</p><h2 id="hydrate-mount-exec" tabindex="-1">Hydrate / mount / exec <a class="header-anchor" href="#hydrate-mount-exec" aria-label="Permalink to &quot;Hydrate / mount / exec&quot;">​</a></h2><p>The three ways to get real files: <code>ws hydrate</code>/<code>exec</code> materialize the ws <em>view</em> (tip + uncommitted ops) to a dir/tmpfs; <code>sturn mount --rw</code> exposes it as a FUSE filesystem where POSIX writes become ops. See <a href="./model.html">model</a>.</p>',20)])])}const u=a(c,[["render",s]]);export{m as __pageData,u as default};
